style.css:
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    background: url("https://i.imgur.com/q6tdz0O.gif") no-repeat center center fixed;
    background-size: cover;
    z-index: -1;
    opacity: 1;
}

body {
    background: none !important;
    color: white;
    text-shadow: 1px 1px 2px black;
}
